(async () => {
    // ============================================================
    // 0. Framework laden
    // ============================================================
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) await fwMacro.execute();

    if (typeof DSK === "undefined") {
        return ui.notifications.error("Das aktuelle DSK-Framework konnte nicht geladen werden!");
    }

    const gabenName = "Mäusemeister";
    const ahne = "Aphasma";
    const finalEffektName = `${gabenName} (${ahne})`;
    const zielEffektName = "Mäusemeister - Wandlung";

    // ============================================================
    // KONFIGURATION DER ZUGELASSENEN MAUS (UUID)
    // ============================================================
    const mausEintraege = [
        "@UUID[Compendium.dsk-core.corebestiary.Actor.BaGVz4HqAZ0QXxsi]{Maus}"
    ];

    globalThis._mausConfigListe = mausEintraege.map(str => {
        const match = str.match(/@UUID\[(.*?)\]\{(.*?)\}/);
        return match ? { uuid: match[1], name: match[2] } : null;
    }).filter(k => k !== null);

    const mausHtml = mausEintraege.map(k => `<li>${k}</li>`).join("");
    const mausNamen = globalThis._mausConfigListe.map(k => k.name);

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    // ============================================================
    // 1. Wirkungsende-Hook (Framework Register)
    // ============================================================
    if (DSK.EffektEnde) {
        DSK.EffektEnde.Register(
            "aphasmaMaeusemeister",
            finalEffektName,
            "Die Verwandlung endet, die Maus verschwindet und das Ziel nimmt wieder seine wahre Gestalt an (inkl. prozentualem LeP/AeP-Abgleich)."
        );
    }

    // ============================================================
    // 2. GLOBALE HOOKS: Präziser Token-Check, Live-Sync & Cleanup
    // ============================================================
    if (!globalThis._mausmeisterGlobalEngineInit) {
        globalThis._mausmeisterGlobalEngineInit = true;

        // HOOK 1: Exakter Check auf frisch platzierte Ziel-Maus
        Hooks.on("createToken", async (tokenDoc) => {
            if (!game.user.isGM) return;
            const actor = tokenDoc.actor;
            if (!actor) return;

            // Exakte Kriterien nach Vorgabe prüfen: type, name, species
            const aType = actor.type; // z.B. "creature"
            const aName = tokenDoc.name || actor.name; // "Maus"
            const aSpecies = (actor.system?.species?.value || actor.system?.details?.species || "").toLowerCase(); // "tier"

            const isExakteMaus = (aType === "creature" && aName === "Maus" && (aSpecies === "tier" || aSpecies.includes("tier")));
            if (!isExakteMaus) return;

            // Suche in der Szene nach dem Ziel mit dem Haupteffekt
            for (let a of canvas.scene.tokens) {
                if (!a.actor) continue;
                const targetEffekt = a.actor.effects.find(e => (e.name || e.label) === finalEffektName);
                if (targetEffekt) {
                    const targetActor = a.actor;

                    // Prozentualen Zustand des Ziels ermitteln
                    const targetLeMax = targetActor.system.stats.LeP.max || 1;
                    const targetLeVal = targetActor.system.stats.LeP.value || 0;
                    const lePercent = targetLeVal / targetLeMax;

                    const targetAeMax = targetActor.system.stats.AeP.max || 1;
                    const targetAeVal = targetActor.system.stats.AeP.value || 0;
                    const aePercent = targetAeVal / targetAeMax;

                    // Maus-Werte prozentual anpassen
                    const mouseActor = tokenDoc.actor;
                    if (mouseActor) {
                        const mouseLeMax = mouseActor.system.stats.LeP.max || 1;
                        const mouseAeMax = mouseActor.system.stats.AeP.max || 1;

                        const newMouseLe = Math.max(1, Math.round(mouseLeMax * lePercent));
                        const newMouseAe = Math.round(mouseAeMax * aePercent);

                        await mouseActor.update({
                            "system.stats.LeP.value": newMouseLe,
                            "system.stats.AeP.value": newMouseAe
                        });
                    }

                    // 1. Ziel-Token unsichtbar machen
                    await a.update({ hidden: true });

                    // 2. Gegenstück-Effekt auf der Maus anlegen
                    if (tokenDoc.actor && !tokenDoc.actor.effects.find(e => (e.name || e.label) === zielEffektName)) {
                        const createdMouseEffects = await tokenDoc.actor.createEmbeddedDocuments("ActiveEffect", [{
                            name: zielEffektName,
                            icon: DSK.Symbol(ahne),
                            description: "Dieses Wesen ist eine verwandelte Person.",
                            flags: { dsk: { targetEffectUuid: targetEffekt.uuid } }
                        }]);

                        const mouseEffect = createdMouseEffects[0];
                        if (mouseEffect) {
                            await targetEffekt.update({ "flags.dsk.mouseEffectUuid": mouseEffect.uuid });
                            await tokenDoc.setFlag("dsk", "spawnedMouseId", tokenDoc.id);
                        }
                    }
                    break;
                }
            }
        });

        // HOOK 4: Live-Sync (Überwacht LeP/AeP über Effekt-UUIDs)
        Hooks.on("updateActor", async (actor, changes, options) => {
            if (!game.user.isGM) return;
            if (options.dskMausSync) return;

            const lePChange = foundry.utils.getProperty(changes, "system.stats.LeP.value");
            const aePChange = foundry.utils.getProperty(changes, "system.stats.AeP.value");
            if (lePChange === undefined && aePChange === undefined) return;

            // Fall A: Maus hat Schaden/Heilung erhalten -> Ziel aktualisieren
            for (const t of canvas.scene.tokens) {
                if (t.actor === actor) {
                    const mouseEff = actor.effects.find(e => (e.name || e.label) === zielEffektName);
                    const targetEffUuid = mouseEff?.getFlag("dsk", "targetEffectUuid");
                    if (targetEffUuid) {
                        try {
                            const targetEffDoc = await fromUuid(targetEffUuid);
                            const targetActor = targetEffDoc?.parent;
                            if (targetActor) {
                                const mouseLeMax = actor.system.stats.LeP.max || 1;
                                const mouseLeVal = actor.system.stats.LeP.value;
                                const mouseLePct = mouseLeVal / mouseLeMax;

                                const mouseAeMax = actor.system.stats.AeP.max || 1;
                                const mouseAeVal = actor.system.stats.AeP.value;
                                const mouseAePct = mouseAeVal / mouseAeMax;

                                const targetLeMax = targetActor.system.stats.LeP.max || 1;
                                const targetAeMax = targetActor.system.stats.AeP.max || 1;

                                await targetActor.update({
                                    "system.stats.LeP.value": Math.round(targetLeMax * mouseLePct),
                                    "system.stats.AeP.value": Math.round(targetAeMax * mouseAePct)
                                }, { dskMausSync: true });
                            }
                        } catch (e) {}
                    }
                }
            }

            // Fall B: Unsichtbares Ziel hat Werte geändert -> Maus aktualisieren
            const targetEff = actor.effects.find(e => (e.name || e.label) === finalEffektName);
            const mouseEffUuid = targetEff?.getFlag("dsk", "mouseEffectUuid");
            if (mouseEffUuid) {
                try {
                    const mouseEffDoc = await fromUuid(mouseEffUuid);
                    const mouseActor = mouseEffDoc?.parent;
                    if (mouseActor) {
                        const targetLeMax = actor.system.stats.LeP.max || 1;
                        const targetLeVal = actor.system.stats.LeP.value;
                        const targetLePct = targetLeVal / targetLeMax;

                        const targetAeMax = actor.system.stats.AeP.max || 1;
                        const targetAeVal = actor.system.stats.AeP.value;
                        const targetAePct = targetAeVal / targetAeMax;

                        const mouseLeMax = mouseActor.system.stats.LeP.max || 1;
                        const mouseAeMax = mouseActor.system.stats.AeP.max || 1;

                        await mouseActor.update({
                            "system.stats.LeP.value": Math.max(1, Math.round(mouseLeMax * targetLePct)),
                            "system.stats.AeP.value": Math.round(mouseAeMax * targetAePct)
                        }, { dskMausSync: true });
                    }
                } catch (e) {}
            }
        });

        // HOOK 2: Effekt endet -> Finaler Prozent-Abgleich, Maus löschen, Ziel sichtbar
        Hooks.on("deleteActiveEffect", async (effect) => {
            if (!game.user.isGM) return;
            const effName = effect.name || effect.label || "";

            if (effName === finalEffektName) {
                const targetActor = effect.parent;
                const mouseEffUuid = effect.getFlag("dsk", "mouseEffectUuid");

                if (mouseEffUuid) {
                    try {
                        const mouseEffDoc = await fromUuid(mouseEffUuid);
                        const mouseActor = mouseEffDoc?.parent;
                        const mouseToken = canvas.scene.tokens.find(t => t.actor === mouseActor);

                        if (mouseActor && targetActor) {
                            const mouseLeMax = mouseActor.system.stats.LeP.max || 1;
                            const mouseLeVal = mouseActor.system.stats.LeP.value;
                            const mouseLePct = mouseLeVal / mouseLeMax;

                            const mouseAeMax = mouseActor.system.stats.AeP.max || 1;
                            const mouseAeVal = mouseActor.system.stats.AeP.value;
                            const mouseAePct = mouseAeVal / mouseAeMax;

                            const targetLeMax = targetActor.system.stats.LeP.max || 1;
                            const targetAeMax = targetActor.system.stats.AeP.max || 1;

                            await targetActor.update({
                                "system.stats.LeP.value": Math.max(0, Math.round(targetLeMax * mouseLePct)),
                                "system.stats.AeP.value": Math.round(targetAeMax * mouseAePct)
                            });
                        }

                        if (mouseToken) {
                            await canvas.scene.deleteEmbeddedDocuments("Token", [mouseToken.id]);
                        }
                    } catch (e) {}
                }

                const targetToken = canvas.scene.tokens.find(t => t.actor === targetActor);
                if (targetToken && targetToken.hidden) {
                    await targetToken.update({ hidden: false });
                }
            }

            if (effName === zielEffektName) {
                const mouseActor = effect.parent;
                const targetEffUuid = effect.getFlag("dsk", "targetEffectUuid");
                if (targetEffUuid) {
                    try {
                        const targetEffDoc = await fromUuid(targetEffUuid);
                        if (targetEffDoc) {
                            await targetEffDoc.delete();
                        }
                    } catch (e) {}
                }
            }
        });
    }

    // ============================================================
    // 3. Ziel ermitteln & Größenprüfung (tiny, small, average)
    // ============================================================
    const targetActor = actor || canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!targetActor) return ui.notifications.warn("Kein Ziel-Akteur gefunden! Bitte wähle das Ziel aus.");

    let whisperTargets = [...new Set([...game.users.filter(u => u.isGM).map(u => u.id), ...getOwners(targetActor)])].filter(id => game.users.get(id));

    const qs = Number(testData?.result?.QL || testData?.qualityStep || 1);
    if (qs <= 0) return ChatMessage.create({ whisper: whisperTargets, content: `${DSK.UI.Header(gabenName, DSK.Symbol(ahne))}<div class="dskbox2"><p style="color:#B30000;text-align:center;"><b>Fehlschlag!</b></p></div>` });

    // Prüfung auf Erwachter / Tier
    if (!DSK.Effekt.CheckTarget(targetActor, "erwachte")) {
        return ChatMessage.create({ whisper: whisperTargets, content: `${DSK.UI.Header(gabenName, DSK.Symbol(ahne))}<div class="dskbox2"><p style="color:#B30000;text-align:center;"><b>Fehlschlag!</b></p><p style="text-align:center;">Das Ziel ist weder ein Tier noch ein Erwachter.</p></div>` });
    }

    // Größenprüfung: tiny, small oder average (winzig, klein oder mittel)
    const zielGroesse = (targetActor.system?.details?.size || targetActor.system?.size || "").toLowerCase();
    const erlaubteGroessen = ["tiny", "small", "average", "winzig", "klein", "mittel"];
    const istGroesseErlaubt = erlaubteGroessen.some(g => zielGroesse.includes(g));

    if (!istGroesseErlaubt && zielGroesse !== "") {
        return ChatMessage.create({
            whisper: whisperTargets,
            content: `
                ${DSK.UI.Header(gabenName, DSK.Symbol(ahne))}
                <div class="dskbox2" style="margin-top:10px;">
                    <p style="text-align:center; color:#B30000;"><b>Gabe fehlgeschlagen!</b></p>
                    <p style="text-align:center;">Das Ziel ist zu groß für den Mäusemeister!<br>
                    <span style="font-size:0.85em; color:#555;">(Erlaubt: winzig, klein oder mittel / Aktuell: ${zielGroesse})</span></p>
                </div>
            `
        });
    }

    const beschreibung = `Das Ziel wird in eine Maus verwandelt. Es behält einen kleinen Teil seiner geistigen Fähigkeiten und Erinnerungen, übernimmt jedoch die körperlichen Fähigkeiten einer Maus. Fehlende Lebens- und Astralpunkte werden prozentual berechnet und live synchronisiert.<br><br><b>Zielkategorie:</b> Tiere und Erwachte (mittel oder kleiner)<br><b>Reichweite:</b> Berührung`;
    const effektBeschreibung = `${beschreibung}<br><hr><b>Verfügbare Maus:</b><ul class="dsklist" style="margin-top:0;">${mausHtml}</ul>`;

    let alterEffekt = targetActor.effects.find(e => (e.name || e.label) === finalEffektName);
    if (alterEffekt) await alterEffekt.delete();

    // ============================================================
    // 4. Haupt-Effekt sauber über das Framework beim ZIEL anlegen
    // ============================================================
    await DSK.Effekt.Anwenden({
        name: finalEffektName,
        ahne: ahne,
        beschreibung: effektBeschreibung,
        gabeZiel: "erwachte",
        qs: qs,
        ziel: targetActor,
        flags: {
            dsk: {
                targetUuid: targetActor.uuid
            }
        }
    });

    // Chatkarte ausgeben
    await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: targetActor }),
        content: `
            ${DSK.UI.Header(finalEffektName, DSK.Symbol(ahne))}
            <div class="dskbox2" style="margin-top:10px;">
                <p><b>Gabenwirkung:</b></p>
                <p style="font-size: 0.9em;">${beschreibung}</p>
                <hr>
                <p><b>Verfügbare Maus:</b></p>
                <ul class="dsklist" style="margin-top:0;">
                    ${mausHtml}
                </ul>
                <hr>
                <p style="text-align:center; font-weight:bold;">Wirkungsdauer: ${qs} Minuten (QS ${qs})</p>
            </div>
        `
    });

})();
